document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("bad-habit-form"),n=document.getElementById("bad-habit-result"),i=e.frequency,t=document.getElementById("custom-frequency");i.addEventListener("change",function(){"custom"===this.value?t.style.display="block":t.style.display="none"}),e.addEventListener("submit",function(i){i.preventDefault();const t=e["habit-name"].value.trim()||"Your habit",r=parseFloat(e.cost.value),d=e.frequency.value,a=parseFloat(e["custom-times"].value)||0;if(!r||r<=0)return n.innerHTML='<p style="color:red;">Please enter a valid cost amount.</p>',void 0;if(!d)return n.innerHTML='<p style="color:red;">Please select how often you engage in this habit.</p>',void 0;if("custom"===d&&(!a||a<=0))return n.innerHTML='<p style="color:red;">Please enter how many times per week for custom frequency.</p>',void 0;let o;switch(d){case"daily":o=7;break;case"weekdays":o=5;break;case"weekly":o=1;break;case"multiple-weekly":o=3;break;case"monthly":o=1/4.33;break;case"custom":o=a}const s=r*o,l=4.33*s,c=52*s,p=10*c,g=.07/12,m=l*((Math.pow(1+g,120)-1)/g),v=e=>"$"+e.toLocaleString("en-US",{minimumFractionDigits:0,maximumFractionDigits:0}),u=e=>"$"+e.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});let y="💸";c>5e3?y="🚨":c>3e3?y="⚠️":c>1e3&&(y="💰");let b="";switch(d){case"daily":b="every day";break;case"weekdays":b="on weekdays";break;case"weekly":b="once per week";break;case"multiple-weekly":b="multiple times per week";break;case"monthly":b="once per month";break;case"custom":b=`${a} times per week`}n.innerHTML=`\n      <div style="background: linear-gradient(135deg, #fff8e1 0%, #fff3c4 100%); padding: 25px; border-radius: 15px; margin: 20px 0; border: 2px solid #ffa726;">\n        <h3 style="color: #e65100; margin-top: 0; text-align: center;">${y} ${t} Cost Analysis</h3>\n        \n        <div style="background: white; padding: 15px; border-radius: 10px; margin: 15px 0; text-align: center;">\n          <p style="margin: 5px 0; color: #666;"><strong>Spending ${u(r)} ${b}</strong></p>\n        </div>\n\n        <div class="insight-cards">\n          <div class="insight-card info">\n            <h6>📅 Weekly Cost</h6>\n            <div class="big-number">${u(s)}</div>\n            <p>${o.toFixed(1)} times per week</p>\n          </div>\n          \n          <div class="insight-card warning">\n            <h6>📆 Monthly Cost</h6>\n            <div class="big-number">${v(l)}</div>\n            <p>About ${(4.33*o).toFixed(1)} times per month</p>\n          </div>\n          \n          <div class="insight-card" style="border-color: #ff5722; background: linear-gradient(135deg, #fff3e0 0%, #ffe0d1 100%);">\n            <h6>📊 Yearly Cost</h6>\n            <div class="big-number" style="color: #ff5722;">${v(c)}</div>\n            <p>${(52*o).toFixed(0)} times per year</p>\n          </div>\n        </div>\n\n        <div style="background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 100%); padding: 20px; border-radius: 10px; margin: 20px 0; border: 2px solid #9c27b0;">\n          <h4 style="color: #6a1b9a; margin-top: 0; text-align: center;">💎 10-Year Financial Impact</h4>\n          \n          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px;">\n            <div style="background: white; padding: 15px; border-radius: 8px; text-align: center;">\n              <h6 style="color: #d32f2f; margin: 0 0 10px 0;">Total Spent</h6>\n              <div style="font-size: 1.8rem; font-weight: bold; color: #d32f2f;">${v(p)}</div>\n              <p style="margin: 5px 0 0 0; font-size: 0.9rem; color: #666;">Money gone forever</p>\n            </div>\n            \n            <div style="background: white; padding: 15px; border-radius: 8px; text-align: center;">\n              <h6 style="color: #388e3c; margin: 0 0 10px 0;">If Invested Instead</h6>\n              <div style="font-size: 1.8rem; font-weight: bold; color: #388e3c;">${v(m)}</div>\n              <p style="margin: 5px 0 0 0; font-size: 0.9rem; color: #666;">At 7% annual return</p>\n            </div>\n          </div>\n          \n          <div style="text-align: center; margin-top: 15px; padding: 15px; background: rgba(255,255,255,0.8); border-radius: 8px;">\n            <p style="margin: 0; font-weight: bold; color: #6a1b9a;">\n              💡 Potential gain from breaking this habit: <span style="color: #388e3c;">${v(m-p)}</span>\n            </p>\n          </div>\n        </div>\n\n        <div style="background: linear-gradient(135deg, #e8f5e8 0%, #c8e6c9 100%); padding: 20px; border-radius: 10px; margin: 20px 0; border: 2px solid #4caf50;">\n          <h4 style="color: #2e7d32; margin-top: 0; text-align: center;">🎯 What You Could Buy Instead</h4>\n          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px;">\n            ${c>3e3?'<div style="background: white; padding: 10px; border-radius: 6px; text-align: center;"><strong>🚗 Used Car</strong><br>Down payment</div>':""}\n            ${c>2e3?'<div style="background: white; padding: 10px; border-radius: 6px; text-align: center;"><strong>✈️ Vacation</strong><br>Nice trip abroad</div>':""}\n            ${c>1500?'<div style="background: white; padding: 10px; border-radius: 6px; text-align: center;"><strong>💻 Laptop</strong><br>High-end computer</div>':""}\n            ${c>1e3?'<div style="background: white; padding: 10px; border-radius: 6px; text-align: center;"><strong>📚 Education</strong><br>Online courses</div>':""}\n            ${c>500?'<div style="background: white; padding: 10px; border-radius: 6px; text-align: center;"><strong>🏋️ Gym</strong><br>Annual membership</div>':""}\n            <div style="background: white; padding: 10px; border-radius: 6px; text-align: center;"><strong>💰 Emergency Fund</strong><br>Financial security</div>\n          </div>\n        </div>\n\n        <div style="background: #fff; padding: 20px; border-radius: 10px; border: 2px solid #2196f3;">\n          <h4 style="color: #1976d2; margin-top: 0; text-align: center;">📈 Break-Even Analysis</h4>\n          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 15px; text-align: center;">\n            <div>\n              <div style="font-weight: bold; color: #1976d2;">Per Day</div>\n              <div style="font-size: 1.2rem; color: #333;">${u(s/7)}</div>\n            </div>\n            <div>\n              <div style="font-weight: bold; color: #1976d2;">Per Hour</div>\n              <div style="font-size: 1.2rem; color: #333;">${u(s/7/24)}</div>\n            </div>\n            <div>\n              <div style="font-weight: bold; color: #1976d2;">Work Hours</div>\n              <div style="font-size: 1.2rem; color: #333;">${(c/3e4).toFixed(1)}h</div>\n              <div style="font-size: 0.8rem; color: #666;">@$15/hour</div>\n            </div>\n          </div>\n        </div>\n\n        <div style="text-align: center; margin-top: 20px; padding: 15px; background: rgba(255,255,255,0.9); border-radius: 8px;">\n          <p style="margin: 0; font-style: italic; color: #666;">\n            💪 <strong>Remember:</strong> Small changes in daily habits can lead to massive financial improvements over time!\n          </p>\n        </div>\n      </div>\n    `})});